const $=sel=>document.querySelector(sel);
const e=(value)=>String(value ?? '').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));
const icon=(name)=>ICONS[name]||ICONS['info']||'';
